check-cost.ts.text:
import assert from "node:assert/strict";
import { readFileSync, writeFileSync } from "node:fs";
const p = import.meta.dir;
const read = (name: string) => JSON.parse(readFileSync(`${p}/${name}`, "utf8"));
const cpu: Record<string, number> = {}, decisions: Record<string, number> = {};
let rows = 0;
for (const epoch of ["ab", "ba"]) {
    const report = read(`cost-${epoch}/development/report.json`);
    assert.equal(report.rows.length, 144); assert.equal(report.metrics.executedTasks, 144); assert.equal(report.metrics.cacheHits, 0);
    for (const row of report.rows) {
        const value = row.execution.processCpuMicros; assert.ok(Number.isSafeInteger(value) && value > 0);
        assert.ok(row.execution.outcome.terminal && row.execution.outcome.decisions > 0); assert.deepEqual(row.execution.outcome.qualityErrors, []);
        cpu[row.arm] = (cpu[row.arm] ?? 0) + value; decisions[row.arm] = (decisions[row.arm] ?? 0) + row.execution.outcome.decisions; rows++;
    }
}
assert.equal(rows, 288);
const ratio = cpu["protect-entrant"] / cpu.current;
const perDecision = (cpu["protect-entrant"] / decisions["protect-entrant"]) / (cpu.current / decisions.current);
const expected = read("cost-verification.json");
assert.deepEqual(cpu, expected.cpuMicros); assert.deepEqual(decisions, expected.authoritativeDecisions);
assert.equal(ratio, expected.completeAdapterCpuRatio); assert.equal(perDecision, expected.weightedCpuPerDecisionRatio);
const qualified = ratio <= 1.10 && perDecision <= 1.10; assert.equal(qualified, expected.qualified);
const result = { qualityPassed: true, independentIntegerCpuAndDecisionTotalsExact: true, completeAdapterCpuRatio: ratio, weightedCpuPerDecisionRatio: perDecision, qualified, physicalGames: rows, subgroupsNotUsedAsGate: true, defaultChanged: false };
writeFileSync(`${p}/independent-cost-verification.json`, JSON.stringify(result, null, 2) + "\n", { flag: "wx" }); console.log(JSON.stringify(result));

check-scouting-contexts-v2.ts.text:
import assert from "node:assert/strict";
import { readFileSync, writeFileSync } from "node:fs";
import { gunzipSync } from "node:zlib";
import { LIVE_PICK_PHASES } from "@heroesofcrypto/common";
import { getDraftScoutingContext } from "@heroesofcrypto/common/src/picks/draft_visibility";
const p = import.meta.dir;
const receipts = JSON.parse(gunzipSync(readFileSync(`${p}/selected-family-receipts.json.gz`)).toString());
let contexts = 0, earlySeeAllMaps = 0, earlyHiddenMaps = 0;
const uniqueContexts = new Set<string>();
for (const receipt of receipts) for (const logical of [0, 1]) {
    const team = logical === 0 ? receipt.candidateTeam : 3 - receipt.candidateTeam;
    const values = [...receipt.deliveryReceipts[logical].map((x: any) => x.context), ...receipt.receipts[logical].map((x: any) => x.contextual.context)];
    for (const context of values) {
        const view = context.publicView;
        const expected = getDraftScoutingContext({ gridType: receipt.task.map, bannedCreatureIds: view.creaturesBanned, phaseOrder: LIVE_PICK_PHASES.map(x => x.phase), phaseLevels: LIVE_PICK_PHASES.map(x => x.creatureLevel), phaseActors: LIVE_PICK_PHASES.map(x => [...x.actors]), phaseSequence: view.phaseSequence, doctrine: view.doctrine, team });
        assert.deepEqual(context.scouting, expected);
        if (view.bundles.length > 0) {
            if (view.doctrine === 2) { assert.equal(context.scouting.map, receipt.task.map); earlySeeAllMaps++; }
            else { assert.equal(context.scouting.map, undefined); earlyHiddenMaps++; }
        }
        uniqueContexts.add(receipt.task.id + ":" + logical + ":" + JSON.stringify(context));
        contexts++;
    }
}
assert.ok(earlySeeAllMaps > 0 && earlyHiddenMaps > 0);
const result = { qualityPassed: true, recordedContextsMatchNativeScoutingProjection: contexts, uniqueDecisionContexts: uniqueContexts.size, repeatedReferencesIncludedInTotal: true, earlyFivePointMapContexts: earlySeeAllMaps, earlyOtherDoctrineMapContextsHidden: earlyHiddenMaps, sourceProviderReusedForDataValidation: true, independentProviderImplementationClaimed: false, defaultChanged: false };
writeFileSync(`${p}/scouting-context-verification-v2.json`, JSON.stringify(result, null, 2) + "\n", { flag: "wx" }); console.log(JSON.stringify(result));
